const body = $json.body || $json;
const email = String(body.email||'').trim().toLowerCase();
if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) { throw new Error('Invalid email address'); }
function uuid(){return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,function(c){var r=Math.random()*16|0,v=c==='x'?r:(r&0x3|0x8);return v.toString(16);});}
function tok(n){var s='';var a='abcdefghijklmnopqrstuvwxyz0123456789';for(var i=0;i<n;i++)s+=a[Math.floor(Math.random()*a.length)];return s;}
const now = new Date().toISOString();
return {json:{
  id: uuid(),
  email,
  full_name: String(body.full_name||body.name||'').slice(0,80),
  keywords: String(body.keywords||'').slice(0,300),
  exclude_keywords: String(body.exclude_keywords||'').slice(0,200),
  locations: String(body.locations||'Istanbul').slice(0,200),
  seniority_levels: String(body.seniority_levels||'Director, VP, CMO').slice(0,150),
  industries_preferred: String(body.industries_preferred||'').slice(0,200),
  sources_enabled: String(body.sources_enabled||'adzuna,jsearch,themuse').slice(0,80),
  language: (body.language==='en'?'en':'tr'),
  tier: 'free',
  status: 'active',
  joined_at: now,
  last_sent_at: '',
  total_reports_sent: 0,
  unsubscribe_token: tok(24)
}};

